"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { BarChart3, Boxes, FolderTree, Image as ImageIcon, Inbox, LayoutTemplate, ScrollText, Settings, ShoppingBag, Tag, Users } from "lucide-react";
import { cn } from "@/lib/utils";

const NAV = [
  { href: "/admin", label: "Dashboard", icon: BarChart3 },
  { href: "/admin/orders", label: "Orders", icon: ShoppingBag },
  { href: "/admin/products", label: "Products", icon: Boxes },
  { href: "/admin/categories", label: "Categories", icon: FolderTree },
  { href: "/admin/leads", label: "Leads & Quotes", icon: Inbox },
  { href: "/admin/customers", label: "Customers", icon: Users },
  { href: "/admin/gallery", label: "Gallery", icon: ImageIcon },
  { href: "/admin/banners", label: "Home Banners", icon: LayoutTemplate },
  { href: "/admin/coupons", label: "Coupons", icon: Tag },
  { href: "/admin/settings", label: "Settings & Staff", icon: Settings },
  { href: "/admin/audit", label: "Audit Log", icon: ScrollText },
];

export function AdminNav({ newLeads, toShip }: { newLeads: number; toShip: number }) {
  const path = usePathname();
  return (
    <nav className="no-scrollbar flex gap-1 overflow-x-auto lg:flex-col">
      {NAV.map(({ href, label, icon: Icon }) => {
        const active = href === "/admin" ? path === "/admin" : path.startsWith(href);
        const count = href === "/admin/leads" ? newLeads : href === "/admin/orders" ? toShip : 0;
        return (
          <Link key={href} href={href} className={cn("group flex items-center gap-2.5 whitespace-nowrap rounded-md px-3 py-2 text-sm transition-colors duration-200", active ? "bg-white/10 font-semibold text-white" : "text-white/70 hover:bg-white/5 hover:text-white")}>
            <Icon className="h-4 w-4 transition-transform duration-200 group-hover:scale-110" aria-hidden />
            {label}
            {count > 0 && <span className="animate-bump ml-auto rounded-full bg-brass px-1.5 text-xs font-bold text-white">{count}</span>}
          </Link>
        );
      })}
    </nav>
  );
}
